//   ├── Error (unrecoverable)
//   │   ├── OutOfMemoryError
//   │   ├── StackOverflowError
//   │   └── NoClassDefFoundError
//   └── Exception (recoverable)
//       ├── RuntimeException (unchecked)
//       │   ├── NullPointerException
//       │   ├── ArrayIndexOutOfBoundsException
//       │   ├── IllegalArgumentException
//       │   ├── NumberFormatException
//       │   └── ArithmeticException
//       └── (checked exceptions)
//           ├── IOException
//           ├── SQLException
//           └── ClassNotFoundException

