HashSet<String> set2 = new HashSet<>(32, 0.5f);          // custom cap & load
HashSet<String> set3 = new HashSet<>(otherCollection);

set.add("A"); set.add("B"); set.add("A");                // "A" only added once
set.remove("B");
boolean present = set.contains("A");

// Set algebra
