  text-decoration: underline;
  text-transform: uppercase;
  text-indent: 20px;
  letter-spacing: 2px;
  word-spacing: 4px;
  line-height: 1.6;
  white-space: nowrap;
  text-shadow: 2px 2px 4px rgba(0,0,0,0.3);
  vertical-align: middle;
}

