  font-size: 24px;
  color: #3498db;
}

/* Bootstrap Icons */
.bi-alarm {
  font-size: 2rem;
  color: #e74c3c;
}

/* Material Icons */
.material-icons {
  font-size: 32px;
  color: #2ecc71;
}

/* SVG inline */
svg.icon {
  width: 24px;
  height: 24px;
  fill: #333;
}

