/* Block-level */
.block-element {
  display: block;
}

/* Inline-level */
.inline-element {
  display: inline;
}

/* Inline-block */
.button {
  display: inline-block;
  width: 120px;
  height: 40px;
}

/* Hidden */
.hidden {
  display: none;
}

/* Visually hidden but space preserved */
.invisible {
  visibility: hidden;
}

