a:visited { color: purple; }
a:hover { color: darkblue; text-decoration: none; }
a:active { color: red; }

/* Removing underline */
a.no-underline { text-decoration: none; }

/* Button-style link */
a.button {
  display: inline-block;
  padding: 10px 20px;
  background: #3498db;
  color: white;
  text-decoration: none;
  border-radius: 5px;
}
a.button:hover { background: #2980b9; }

