  // risky code
  JSON.parse(invalid);
} catch (err) {
  console.error(err.name);    // "SyntaxError"
  console.error(err.message); // "Unexpected token..."
  console.error(err.stack);   // stack trace
} finally {
  console.log('cleanup');
}

throw new TypeError('Invalid type');

