// Constants
const MAX_USERS = 100;

// Variables
let count = 0;
const name = 'Alice';

// Functions
function calculateTotal(items) { /* ... */ }
const double = (x) => x * 2;

// Class
class UserRepository { /* ... */ }

// JSDoc
/** @param {number} a @param {number} b @returns {number} */
function add(a, b) { return a + b; }

