class ClassName {
    // Properties
    public $prop1;
    private $prop2;
    protected $prop3;

    // Methods
    public function methodName($param): returnType {
        $this->prop1 = $param;
    }
}

// Creating instances
$obj = new ClassName();
$obj->prop1 = "value";
$obj->methodName("value");

// Type hinting
function processClass(ClassName $obj): ?string {
    return $obj->methodName("test");
}

